quests[70661] = { id = 70661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies on High" }
quests[70662] = { id = 70662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bone to Pickaxe" }
quests[70697] = { id = 70697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Expert Opinion", description = "Lubbins' wounds may have healed, but I am afraid his confidence may still be injured. I believe it is time to call on others for help.\n\nFar to the southwest in a remote section of the Azure Span there is a pet trainer named Patchu. She is one of the world's foremost experts on these matters.\n\nPlease visit her, I am sure she can help Lubbins!", completion = "Jyhanna sent you to the right Tuskarr, {name}. We'll get Lubbins back to his old self in no time!", objectives = "Talk to Patchu in The Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70698] = { id = 70698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researcher Sneakwing" }
quests[70699] = { id = 70699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataloging Thaldraszus" }
quests[70701] = { id = 70701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bakar Dream of Lost Argali", description = "Some of the clan's argali have wandered away from our flock again.\n\nThe ridge around us is too dangerous for our shepherds to search for them. It would be a great boon if you could take one of our bakar and bring back the argali. Our shepherds can point you in the right direction.", completion = "We must be vigilant about our livestock. We are limited in resources to begin with. To lose an argali is a setback we would much like to avoid.", objectives = "Herd the lost argali back to Clan Aylaag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70702] = { id = 70702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Waygate Exploration", description = "<The little messenger's loud, screeching call captures your attention. They hand you a note before running off.\n\nThe note is a request from Thaelin Darkanvil, seeking your assistance.>", completion = "I see ye found me letter. Glad tae see ye again!", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70703] = { id = 70703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legacy of Tyrhold", description = "Keeper Tyr did love his mysteries. Clearly, there is deeper meaning to the gift he gave us. As he most likely forged this scale at his former citadel, perhaps it will be the key to helping unlock its secrets.\n\nGo with Koranos to Tyrhold, {name}. As a trusted advisor and watcher of this land, I am sure he will have insight into this matter.", progress = "Have you discovered something?", completion = "That magic... You have awakened something within Tyrhold.", objectives = "Investigate the Silver Scale with Koranos at Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70706] = { id = 70706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waygate: Shady Sanctuary", description = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", objectives = "Locate the Dormant Waygate at the Shady Sanctuary in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70707] = { id = 70707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Next Waygate", description = "I've been keepin' this here vessel from yer nightborne friend safe.\n\nWhat do ye say 'bout us puttin' it tae good use and pursuin' another of those old stones?", objectives = "Choose the next waygate location to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70708] = { id = 70708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollow", description = "Feels like it's been years. Also feels like it's been minutes. \n\nI could use someone to talk to, if you have time. \n\nYou wanna grab us a round of drinks? Get whatever you want. I'm paying.", progress = "I know I owe you more than a drink, but I hope this will do for now.", completion = "It's time to go, I guess.", objectives = "Have a drink with Kolgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70710] = { id = 70710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "River Rapids Route", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
