quests[70720] = { id = 70720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Have These" }
quests[70721] = { id = 70721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After My Ohn Heart", description = "There is a small pond by the Mirror of the Sky where Narman and I first met during my initiate training.\n\nInitiates travel up there to be closer to Ohn'ahra so they may feel the wind. I first saw him in the reflection of the water when a sudden breeze opened my eyes. It is the most beautiful sight in all of the plains.\n\nIt will be the perfect place for our proposal.", completion = "Thank you, {name}.\n\nDawa and I will always remember what you have done for us.", objectives = "Help Windsage Dawa and Hunter Narman with their proposals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70722] = { id = 70722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lubbins Needs", description = "I think that I know what we gotta do, {name}. \n\nBut first, let's talk about it!\n\nI even have a gift to give you after we're done! Fun, right?", progress = "Let's talk!", completion = "Make sure to summon Lubbins, then use this battle-stone on him. It'll permanently make him stronger.", objectives = "Speak with Patchu in Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70723] = { id = 70723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattering the Earth Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", completion = "This will help further our research on the Primalists. Thank you.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70730] = { id = 70730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shikaar Giver", progress = "Narman deserves a gesture as great as he is.", completion = "Arbhog's horns? They'll do just fine.\n\nArbhog was once the mightiest musken on the plains. These are a fitting gift for the mightiest hunter. I am sure Narman will appreciate them.\n\nPerhaps one day he will teach me to hunt. An Ohn'ir huntsman. Ha! Imagine that.", objectives = "Help Windsage Dawa prepare for the perfect proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70732] = { id = 70732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Practice Bout", description = "All right! Now that you used that stone on Lubbins, let's have a practice bout to test out his skills! \n\nThere's a big ole Hornswog named Gwosh that lives on the shore to the north of here. Gwosh loves to fight! Well, play really. He's super good with other pets, too! \n\nIt'll be a perfect playtime... I mean fight... for Lubbins.", progress = "Gwosh is real gentle, but still fierce. I think he and Lubbins will have a fun bout! \n\nJust head up north of here and you'll find him.", completion = "Wow! That went great! Good job Lubbins!\n\nDon't worry about Gwosh, he's a big ol' softie. He'll be just fine.", objectives = "Defeat Gwosh in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70738] = { id = 70738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The You-ga Class", description = "Everything was going so well, but now? Elementals are causing some, um, mild challenges.\n\nOur guests were enjoying the facilities when suddenly, all these elementals appeared! Those nasty fiends have disrupted everything. Probably even the new you-ga instructor. \n\nOh yes, you-ga is a new type of stretching that helps you meditate at the same time. I am sure both teacher and students are so relaxed they do not even notice the elementals.\n\nStill, better to be safe than sorry. Please, look for them.", completion = "Hopefully this experience won't tarnish their reviews!", objectives = "Find the instructor and 6 you-ga students.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70739] = { id = 70739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodlines, Sweets, and Teerai", description = "I have hunted with khans, outrun our fastest bakar, and wrestled a full grown bruffalon bull bare-handed. As a hunter, I've nothing left to prove.\n\nHowever, as a partner, I still have much to learn. \n\nWindsage Dawa of Clan Ohn'ir is my heart and my joy. I wish only to prove worthy of his love, but I know nothing of traditions and rituals. I require the wisdom of the elders in Maruukai.", progress = "What if I am not good enough for Dawa's love?", completion = "I would sooner ask all the stars of the night sky to admire me back than claim to be wholly worthy of Dawa's love.\n\nNonetheless, I will find the courage to proceed. When the time comes, will you assist me with a grand proposal?", objectives = "Help Hunter Narman earn a traditional blessing for his marriage proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70740] = { id = 70740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steam Cleaning", description = "Xijan seems to think the elemental invasion on our beautiful spa is only a minor problem, but this surge of flame and steam needs to be brought under control immediately.\n\nWe had booked musical acts to play in the lower area, but the elementals destroyed their gear. As we have never had such levels of elemental destruction in this area before, I suspect Primalist influences.\n\nIf you want to help, clear the elementals on the east side of the lower spa. That is where the first events are scheduled.", completion = "A good start, but there are still far too many for my liking...", objectives = "Kill 12 elementals in the lower spa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70741] = { id = 70741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Favorite Things", description = "<It looks like the you-ga class was interrupted, and the students' belongings are scattered everywhere. \n\nCollecting these items will certainly aid the Serene Dreams Spa.>", completion = "It is very kind of you to gather these items. We will return them to their owners right away!", objectives = "Collect 6 missing belongings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70742] = { id = 70742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runs in the Family", description = "From the air, I scouted one of the artifacts Edress uncovered by the entrance of the ruins. Doubtless there are more inside.\n\nThey are warded somehow, though I will need to get closer before I can examine them. The magic here is very old.\n\nThe grounds appear deserted, but I wouldn't trust that to last long once we start meddling. Keep an eye out. We will uncover all we can.", completion = "This has given me... much to ponder. I would prefer some time alone, if it's all the same.", objectives = "Search the Obsidian Observatory for clues about the dracthyr's past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70743] = { id = 70743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Baby", completion = "<Elzara ignores you and looks at Baby.>\n\nAre you safe, my precious cuddlemuffin?\n\nDid the Primalists bleed on you? How dare they!\n\n<Elzara notices you.>\n\nI shall definitely be rating this spa at one star. I expect a blood-free experience.", objectives = "Find Elzara's Baby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70744] = { id = 70744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look at the Bones!", description = "<Surely the spa manager would appreciate if there wasn't blood everywhere...>", completion = "I do not want to know, do I?", objectives = "Clean up 10 bits of mess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70745] = { id = 70745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enforced Relaxation", description = "Those Primalists that you saw certainly do not seem like the leadership type to me. Who would be afraid of a little dog? Hah!\n\nSo, if they mentioned Vadne, that sounds like their leader. She must be the one bringing in these elementals. We need to get rid of the summoner. They must be close by to be causing such trouble. Check the cave directly under us. I know it is where some of the less diligent employees like to take an extended break.", completion = "I am glad this will finally start to get better! We all deserve a little bit of downtime.\n\nI hope you find a short respite here as well: you have earned it, {name}.", objectives = "Kill the elemental summoner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70746] = { id = 70746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shades of Blue", progress = "Keep your head clear and your wings ready, my friend.", completion = "No sign of blue dragons yet, but plenty of their underlings.", objectives = "Accompany Emberthal and Telash to Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70747] = { id = 70747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Wizard", progress = "You appear uneasy, friend.", completion = "On behalf of the Kirin Tor, I'm deeply concerned to hear what Malygos did to your people. \n\nThis demands an immediate investigation.\n\n... Where are your companions?", objectives = "Talk to Archmage Khadgar in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70748] = { id = 70748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Blue Eyes Only", description = "It is no wonder your companions have yet to find anything. \n\nThese books were meant for blue eyes only. \n\nHowever, my presence should suffice in allowing for some of the more pertinent tomes to divulge their secrets.", progress = "Have you found that which you seek?", completion = "You have the answers you seek, yet you do not look content...\n\nI am sorry.", objectives = "Search the Azure Archive for Malygos's notes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70750] = { id = 70750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord", description = "You there! Yes, I'm speaking to you. Who else do you see around here?\n\n<Therazal glances quickly at quite a few passers by.>\n\nIgnore them. They are not part of this request. It is you I've heard of, and you I wish to speak with!\n\nThe Valdrakken Accord has asked me to seek out those who have shown they are making a name for themselves across the Isles, and those who seek to ensure our allies and their safety remain the highest priority.\n\nDo what you do best, friend. You shall be rewarded handsomely.", progress = "The tales of your exploits ring true, but what is it you bring me? Information, news? Get on with it.", completion = "Yes, indeed I am impressed, friend. As a representative of the Accord I can assure you your work has not gone unnoticed!\n\nPlease, accept this on behalf of our allies.", objectives = "Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70751] = { id = 70751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terillod the Devout" }
quests[70752] = { id = 70752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaporizing the Water Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", completion = "This will help further our research on the Primalists. Thank you.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70753] = { id = 70753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dissipating the Air Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", completion = "This will help further our research on the Primalists. Thank you.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70754] = { id = 70754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing the Fire Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", completion = "This will help further our research on the Primalists. Thank you.", objectives = "Bring the primal core to Rethelshi.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70763] = { id = 70763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldcarver A'tir" }
quests[70766] = { id = 70766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fractured Flame", description = "The gorloc clutches a journal, its cover marred by moisture and lack of care. The faded symbol of the Sundered Flame peeks proudly from behind the tears and discoloration.\n\nIf you find the missing pages, perhaps you can gain insight into Reclaimer Makko and the madness that has fractured her mind.", progress = "A journal? Written by who?", completion = "Thanks, but you can keep it. \n\n<Toddy rolls her eyes.>\n\nAnd I thought the Sundered Flame were crazy before...", objectives = "Collect the pages of Makko's Journal from gorlocs in Szar Skeleth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70779] = { id = 70779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarjin's Tales", description = "<Tarjin continues facing the distant island while he speaks to you.>\n\nYou think yourself worthy of the incredible legends and histories of the djaradin?\n\nYou, who are hardly the size of one of our weapons? Pfft.\n\nI doubt you have the stomach to carry the legacy of my people.\n\nProve me wrong, if you can. Seek out dragons, the only worthy rival on these isles.\n\nBring me trophies of your victory over their strongest.", progress = "If you haven't the stomach to fight your precious dragonflights, you may seek out the proto-dragons. They still give quite a fight.", completion = "<Tarjin tosses the skulls over his shoulder into the lava pit behind him.>\n\nImpressive, for a weakling.", objectives = "Collect 5 Impressive Dragon Skulls from powerful dragons and proto-dragons in the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70780] = { id = 70780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohn'ahran Banners" }
quests[70781] = { id = 70781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Blue", description = "Did you see that?!\n\nThis winged creature just fell from the sky! I don't know what sort of being it is, but it certainly isn't native to the Isles.\n\nWait... I do remember a punchy little goblin asking for directions to the Bluefeather Cliffs just above us. You think she would know anything about it?", completion = "Some guard in Gelikyr told you I'd be here? Did they say I own 'em any money?", objectives = "Locate Harleen Chirpsnide in the Bluefeather Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70782] = { id = 70782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canopy Banners" }
quests[70783] = { id = 70783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skaara" }
quests[70784] = { id = 70784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Outpost", description = "From what you mentioned, it appears the stone of Vigilance can be found at an abandoned station northeast of the Azure Archives. That must be Zelthrak Outpost.\n\nMeet up with me when you arrive, {name}, and we can find the stone together.", completion = "I know this place is abandoned, but I didn't think it would be so... messy.", objectives = "Meet up with Naleidea near Zelthrak Outpost in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70785] = { id = 70785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The City of the Dead", description = "An ancient city of the dead can only mean one thing. The Veiled Ossuary off the coast of northern Thaldraszus.\n\nIt's extensive, remote, and hard to approach. The perfect place to hide something. I'm not sure what we'll find there, {name}. But you can bet that it won't appreciate our presence.", completion = "Good, you're here! The sooner we begin the sooner we can leave.", objectives = "Meet up with Naleidea at the Veiled Ossuary in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70787] = { id = 70787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught In a Dusk Storm" }
quests[70788] = { id = 70788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrapped Gold Band", description = "<This might be something Emila Bellocq is looking for.>", completion = "Beautiful. I will put this away so it's safe.", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70789] = { id = 70789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finely Carved Wing", description = "<This might be something Emila Bellocq is looking for.>", completion = "It's so delicately carved... We have really lost some fine techniques over the ages. I'll take this and make sure its safeguarded.", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70790] = { id = 70790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Dragontooth", description = "<This might be something Emila Bellocq is looking for.>", completion = "It's very old, but you can still tell what it is... I will make sure this is filed away safely.", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70791] = { id = 70791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldwashed Dragonclaw", description = "<This might be something Emila Bellocq is looking for.>", completion = "What a colossal statue this must have been! And now we only have... this. But at least we have something! I'll make sure we get it logged.", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70805] = { id = 70805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Stone Fragments", description = "<This might be something Emila Bellocq is looking for.>", completion = "I wonder what it would have looked like when it was new? Awe inspiring, I'll bet. For now, it's going into a box under lock and key!", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70806] = { id = 70806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chunk of Sculpture", description = "<This might be something Emila Bellocq is looking for.>", completion = "Hm.\n\n<Emila turns the piece over, looking at it from different angles.>\n\nPerhaps? No, I can't tell what it is. It's old though and undoubtedly important. In the collection it goes!", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70807] = { id = 70807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Excavation Tools", objectives = "We appreciate your continued help with the expedition! As a reward for your efforts, I want to offer you one of my advanced tools. I have all of these tools available for trade, so come and see me again if you'd like another.\n\nThank you, adventurer!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70808] = { id = 70808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Initial Mysteries of the Dragon Isles Drakes", objectives = "Dragons have long fascinated me. Being here is a dream come true! I have already learned much about the renewed proto-drakes of the Waking Shores. Would you like to see one of the manuscripts I have put together? I have made many observations, and would be willing to trade for others as well!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70809] = { id = 70809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper Mysteries of the Dragon Isles Drakes", objectives = "I have made great progress since we last spoke, adventurer! Please, choose another manuscript to help your renewed proto-drake learn another trait. Do not forget, you may always speak with me if you would like to trade for others!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70810] = { id = 70810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broader Mysteries of the Dragon Isles Drakes", objectives = "I was able to expand my studies to the other drakes of the Dragon Isles. The red scales most common to the renewed proto-drakes are not limited to their variety. Each of the other main drakes can show red scales as well! Please, choose a manuscript for the drake you prefer. If you wish to trade for the others, come see me again!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70811] = { id = 70811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expert Excavation Tools" }
quests[70812] = { id = 70812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Cloaks", objectives = "A good cloak can be the most essential piece of gear on an expedition. Your help's earned you your choice of cloak. See me if you want to trade for a different one.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70813] = { id = 70813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Up Treasure", objectives = "Most of the treasure around here is in the ground--ancient artifacts, maybe even valuables. You're going to need a good shovel to get to it, though. Lucky you, I've got an official expedition shovel with your name on it. Look for disturbed dirt, and see what you can find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70814] = { id = 70814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking Magical Treasures", objectives = "This place has many treasures you have yet to see, as they are bound in magic. I can teach you to see them. Many lie hidden deep within caves, or are magically locked away in the various ruins of the land. Good luck in your search!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70815] = { id = 70815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolitions Access", objectives = "Some excavations require a delicate touch, and others need something a little more explosive. I think we can trust you to know when to use which. You can have this first explosive for no trade. Use it wisely, and don't prove me wrong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70816] = { id = 70816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Tracking Techniques" }
quests[70817] = { id = 70817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Dragonscale Equipment", objectives = "The Dragonscale Expedition has access to some of the best artisans in Azeroth. They've created excellent equipment to help with exploration. Why, we just received a shipment of fine gloves. Take a look at my wares to see if they're something you want to trade for.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70818] = { id = 70818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Dragonscale Equipment", objectives = "A shipment of well-crafted leg armor just arrived. If you see something you like, let me know, and we can trade for it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70819] = { id = 70819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned Explorer's Armor", objectives = "You've done some great things, adventurer--and it hasn't gone unnoticed. The expedition leadership has authorized me to issue you a set of our best armor. Thank you for all your help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70820] = { id = 70820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basecamp 'Pets'", objectives = "Ach! I thought a lifetime of gryphon wrangling would have prepared me for taming the unruly beasts of the Dragon Isles. But these Marmoni and Skitterbugs are pushing me to my limits! I will gladly offload one to you. If you seek another, I'll offer ye a fair trade!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70821] = { id = 70821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skitterfly Riding", objectives = "Who woulda known that caring for juvenile skitterbugs would have consequences? Their parents, Skitterflies, came looking for them. Rather than wanting a fight, they nested--just like a gryphon would! I started training them and wouldn't you know it, it's close to riding a gryphon... once you get used to the buzzing wings. With all the help you're providing around here, I'd like you to have your first Skitterfly mount on me. I will gladly train you another, in exchange for some very specific items.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70822] = { id = 70822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Expedition Scouts", objectives = "We've sent out plenty of scouts since we landed, and a fair number of them haven't returned. Could you keep an eye out for them while you're exploring? They can often be spotted with our standard issue Expedition Scout Pack. Oh, and if you find any artifacts, deliver them Cataloger Jakes. She'll appreciate it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70828] = { id = 70828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayfinder's Compass", objectives = "These lands are vast--the terrain rises so much that it's easy for even the most knowledgeable tracker to get lost. If you want to help us out, you'll need a way to navigate. Take this compass, it should do the trick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70829] = { id = 70829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataloging Expeditions" }
quests[70830] = { id = 70830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packing for a Climb", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70831] = { id = 70831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching in Comfort", objectives = "Many hours of expedition work is spent--how do I say this? On your behind. I do not see why we can't make that time a bit more comfortable. Therefore, I have asked our new allies in the Reliquary to fashion us a set of pillows that will do nicely. I will let you have your pick, but you will have to trade if you want more!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70832] = { id = 70832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of Us Now", objectives = "You're just the type of adventurer we want in our expedition, and we're so glad to have you! To show our appreciation, I'd like to reward you with our tabard. It'll show the world everything you've accomplished! We can't forget our roots, though--if you'd like a banner for the Reliquary or the Explorer's League, I have those available as well. Thank you for everything you've done!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70833] = { id = 70833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumors of the Jeweled Whelplings", objectives = "Have you heard the tale of this ancient jewelcrafter from the Dragon Isles? Legend has it they had a technique to craft jeweled whelpling statues that would come to life. I took it for just a story as well, but then this map was found in the pack of one of our fallen scouts with a clue to a jeweled whelpling. Take the map, see if it leads to the secret of creating these fabled living statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70834] = { id = 70834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titled Story", objectives = "I've been cataloging every deed and artifact that every member has contributed to the Dragonscale Expedition since we landed. Today I noticed the sheer height of your accomplishment. I could not be prouder to bestow upon you this prestigious title and this coveted Primal Infusion item that you can have crafted into a powerful item. Go forth and carry it as a true accomplishment for your heroic efforts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70835] = { id = 70835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturdy Expedition Shovel", objectives = "<Boss Magor waves you down.>\n\nHey there blacksmith, I've a new pattern you might be interested in!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70837] = { id = 70837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow the Clues", description = "<Investigator Erima reviews the map.>\n\nIt is clear what the X scrawled over the Seat of the Aspects represents.\n\nBut there is also a circle drawn around the Misty Vale. Perhaps this is the rebels' next target? Or a base of operations.\n\nOnly one way to find out. Meet me at the Vale.", completion = "This is definitely a base of operations.\n\nThe Misty Vale is crawling with rebels... and Primalists!", objectives = "Meet Investigator Erima at the Misty Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70838] = { id = 70838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebels With a Cause", description = "The rebel staging ground... we have been looking for this very place. How fortunate for us that their saboteur's carelessness led us here.\n\nI cannot believe my brethren would stoop to working with the Primalists. We cannot let this stand. Take out the rebels and their Primalist friends before they can cause any further chaos.", progress = "I trust these turncoats will pose no threat to you.", completion = "You handled yourself well.\n\nThese rebels are no slouches.", objectives = "Kill 10 rebels and Primalists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70839] = { id = 70839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Titan Relics", objectives = "I have spent all of my time since the waking studying the titans. Their history is fascinating. What power they must have wielded to create the dragonflights! There is so much knowledge to be gained about them! \n\nIf you could bring me any titan relics you find around the Dragon Isles, I will put in a good word for you with the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70840] = { id = 70840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titan Relic", progress = "Have you found a Titan Relic?", completion = "Amazing! This relic is perfectly preserved. I will begin studying it right away.\n\nYour efforts are most appreciated! I will remember my promise to speak well of you to the Valdrakken Accord. \n\nNow, where was I? Yes, this will fit in right over here..." }
quests[70841] = { id = 70841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Titan Relics", progress = "What have you brought me today?", completion = "How did you find so many of these? This is a veritable treasure trove of relics! One day you must tell me your secret. \n\nOnce again you have greatly increased our knowledge of the titans. The Valdrakken Accord will think well of you indeed!" }
quests[70842] = { id = 70842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation Locations", description = "I am sure that the rebels are documenting their plans for future attacks. We must find out what they are attempting to do before it happens.\n\nSearch their camp for any marked maps like the one we found in Valdrakken.", progress = "Were you able to recover the rebel plans?", completion = "I will send word to step up our security measures in these locations.", objectives = "Collect Misty Vale maps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70843] = { id = 70843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruin the Runestones", description = "<This runestone is strikingly similar to the one a rebel tried to plant in Valdrakken.\n\nThough this stone is unfinished, you spy caches of completed runestones off in the distance.\n\nIf you destroy these caches the rebels will not be able to put them to use.>", progress = "Brave of you to tinker with those strange stones.", completion = "I could feel the tremor of those explosions all the way from here!\n\nValdrakken is now safer, thanks to your efforts.", objectives = "Destroy caches of incendiary runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70845] = { id = 70845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tyr's Footsteps", description = "Keeper Tyr planned for all eventualities. He suspected there would be a need to empower the craftspeople of the realm some day, thus he created the Engine of Innovation. It possesses the ability to create a unique material that can help an item achieve expertise beyond that of mortal ability.\n\nTo ensure his engine would not be misused he created me to oversee any who sought its power. Only those worthy will be able to unlock the engine's full potential. \n\nAre you equal to the challenge?", completion = "<It feels as if the statue reacts to your presence, its mechanism slowly awakening and coming to life.>", objectives = "Find the First Challenge of Tyr in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70847] = { id = 70847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Obsidian Charm", description = "<Talonstalker Kavia might want this.>", completion = "It's still intact. Hopefully it brings the next owner more luck.", objectives = "Deliver the item to Talonstalker Kavia.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70848] = { id = 70848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Dragon Crest", description = "<Exadria might want this.>", completion = "This crest belonged to the first dragons that lived in this Citadel. We shall display it in a place of honor.", objectives = "Deliver the item to Exadria.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70849] = { id = 70849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Calls for a Specialist", description = "Lubbins is doing lots better now, but I think he still needs some more help. \n\nA little bit ago I met a super smart Dragonscale Expedition explorer named Haniko who works with proto-drakes all the time. She's a pet trainer, too. I bet she could help Lubbins more! \n\nI think she was going to the Waking Shores. I bet if you go there you'll find her. \n\nI'm so happy I was able to help you! \n\n<she waves happily>\n\nGoodbye! Good luck, Lubbins.", completion = "Patchu was right to send you here. I've been working with proto-drakes my whole life. \n\nI don't know if there's anyone on Azeroth who knows more about them than I do.", objectives = "Talk to Haniko at the Wild Preserve in The Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70850] = { id = 70850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldra's in Hot Water", description = "Excellent work. While you were off disrupting things I was scouting the camp. I did not expect to find my old friend Maldra Flametongue.\n\nI knew she was missing, but the rumors said she had joined the rebels. From what I could see, though, she is their captive!\n\nWe cannot leave her here. Rescue her from the dragonspawn holding her captive!", progress = "Maldra is a dear friend. We cannot leave her here with these rebels!", completion = "I am indebted to you for rescuing my friend.", objectives = "Rescue Maldra from Orian Darkwater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70851] = { id = 70851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Born to Be Wilder", description = "There's a lot of information you need to know. Let's have a talk and then we can decide what's best for Lubbins.", progress = "There's a lot to cover. Let's talk.", completion = "Good! Now to get to work, {name}.\n\nBefore you go, take these polished pet charms. Pet trainers like to trade these for useful supplies, so keep an eye out.", objectives = "Learn what Lubbins needs from Haniko.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70853] = { id = 70853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend for Lubbins", description = "Like we talked about, Lubbins needs two things: a buddy and a battle.\n\nI think we can get him both at the same time.\n\nThis area is a prime mating ground for Shyflys. If you look around a bit, you're sure to find a bunch.\n\nRemember, you need to weaken it before you can capture it with your trap.\n\nCome back when you have one. It might be a bit bruised after your battle, but I've got some battle-training stones that will fix 'em right up!", progress = "The Shyflys shouldn't be too hard to find, especially now that you know where to look.", completion = "Nicely done. I believe these battle-stones are just what your new pet needs. \n\nYou know what? Take a few polished pet charms too. \n\nDid I mention you can trade them for good stuff? Because you can!", objectives = "Capture a Shyfly at the Wild Preserve in The Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70854] = { id = 70854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So How Did It Go?", description = "You've done well, {name}. Lubbins is doing much better and is in excellent spirits. \n\nJyhanna will want to know, so go back and give her the good news!", completion = "I am so glad you were able to help Lubbins. \n\nPerhaps you can help another animal I rescued. His name is Mister Toots. He is extremely sweet, and I think you two would get along.\n\nWhat do you say? Do you think you can handle another pet?", objectives = "Return to Jyhanna at the Whelp Daycare in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70856] = { id = 70856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill it with Fire", description = "These vile spiders lay their eggs in corpses.\n\nAnd sometimes the living.\n\nWe've seen several bodies of Sundered Flame who have fallen victim to them.\n\nWe can't let those eggs hatch if we want to survive here and defeat the Sundered Flame.\n\nTake this torch. It is imbued with the power of air and fire. Point it in the direction of what you want scorched, and it will do the rest.\n\nThe Tuskarr don't mess around with spiders. I came prepared.", completion = "Good work. This should give us some breathing room.", objectives = "Destroy 10 Infected Corpses with the Flamethrower Torch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70858] = { id = 70858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back into the Action", description = "All right, the antidote is ready. I'll keep Alia steady. You pour what's in the vial into her mouth.\n\nI hope she will live... we'll need her magic to track down this artifact.", completion = "You have my thanks... I thought I would die before acquiring this artifact.", objectives = "Use the Ice Cold Antidote on Alia Sunsoar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70859] = { id = 70859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Guardian Beholds", description = "I appreciate your aid, {class}. I was the Kirin Tor mage who first discovered this artifact, Valthrux, and the Sundered Flame's plans.\n\nThe retrieval and study of this supposedly sentient and powerful artifact is of the utmost importance, and mark my word, I shall be the one to do it.\n\nThe Sundered Flame guess at its location, but I've used my magic to find a path for us.\n\nThere is a corrupted guardian nearby that holds a magic shard connected to Valthrux. I can use it to find the rest of the artifact.", progress = "Did you find the shard?", completion = "Give it to me! Quickly now!\n\nDid you hear the whispers too?", objectives = "Recover the Whispered Shard from Edavix, the Corrupted Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70867] = { id = 70867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalebane Keep" }
quests[70871] = { id = 70871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskaaran Fishing Net", description = "I see you're getting along with the villagers.\n\nYou seek to learn more about our ways of fishing you say? Well, first of all no one fishes with their bare hands. I can craft you a good, strong net worthy of an Iskaaran.", progress = "Have you found suitable materials? I need strongest vines of kelp, and some good stones with holes in them.", completion = "Here's your Iskaaran fishing net. Use it wisely, and never take from the cycle of life more than you need to sustain yourself.", objectives = "Bring Tavio materials and let her craft an Iskaaran fishing net.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70873] = { id = 70873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Waterfalls", description = "The real threat lies in the Emberslate Cavern. This is where they carve those runestones and infuse them with primal fire.\n\nNo doubt you noticed the blazing wall of flame that blocks the entrance. I cannot dispel it, however I may be able to do something to help. I believe that with the proper application of Fallingwater, we can pass through it safely.\n\nHarvest water motes from the nearby elementals.", progress = "We will need those motes to get you safely into the Emberslate Cavern.", completion = "<Maldra examines the Fallingwater Motes.>\n\nYes, these should do nicely.", objectives = "Harvest 35 Fallingwater Motes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70874] = { id = 70874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Breach a Fire Wall", description = "The rebels inside the cavern have been imbued with an elemental blessing, allowing them to safely pass through the wall of flame. I can grant you that same boon.\n\nDo not worry; I have seen the blessing granted many times. It shouldn't be any problem to recreate it effectively.", progress = "How do you feel?", completion = "Worry not. That chilly, damp feeling is temporary.", objectives = "Receive Maldra's elemental blessing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70875] = { id = 70875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worst of the Worst", description = "The rebels in the Emberslate Cavern have an unflinching loyalty to the Primalists, and are therefore the greatest threat to Valdrakken.\n\nEliminate them, and any elementals they have unleashed.", completion = "Well done, {name}.\n\nThose who follow the Primalists cannot be allowed to spread chaos and destruction.", objectives = "Kill 3 rebels and 4 elementals in Emberslate Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70876] = { id = 70876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fracture the Foci", description = "If Maldra speaks the truth, the rebels are creating the runestones in the Emberslate Cavern.\n\nGiven the nature of these devices, we know there must be Primalist foci involved.\n\nDestroy the foci. You will know them when you see them.\n\nThe rebels cannot be allowed to create any more weapons of destruction.", completion = "Without those foci, the rebels will no longer be able to imbue their runestones with explosive flame.", objectives = "Destroy 4 Primalist Foci in Emberslate Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70877] = { id = 70877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quack in Time", description = "<This duckling is despondent, quietly quacking to itself as its eyes dart around in fear.>\n\n<Maybe the ecologists would know how to help it?>", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And {name} too, of course.", completion = "Thanks for bringing Daisy to us. If there's two so far, there must be more, so keep an eye out next time you venture out there.", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70878] = { id = 70878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Fire", description = "In the deepest recesses of the Emberslate Cavern, the Primalists erected a fiery portal from which they unleash elementals.\n\nI can seal it, but my actions will draw the ire of whatever is on the other side. Including the revenant Magmaticus the Primalists have been aiding.\n\nI will need your protection if we are to stop them.", completion = "Nicely done, {name}!\n\nMaldra shared with me the details of your heroics.", objectives = "Protect Maldra Flametongue while she seals the Primalist portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70879] = { id = 70879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report on the Rebels", description = "I am impressed with what you have accomplished today. I hope you agree, {name}.\n\nWe have successfully shut down the nefarious activities of these Primalist-allied rebels. For now at least. We will need to keep a close watch on any dissent going forward.\n\nReturn to Captain Drine at your earliest convenience. She will want our full report.", completion = "Welcome back, {name}.\n\nMy eyes and ears have just told me the good news.", objectives = "Meet Captain Drine at the top floor of the Seat of the Aspects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70880] = { id = 70880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Cook With Finery", objectives = "Hello there. Can I offer you a fork? Or maybe some tea?\n\nIt is a pleasure to see so many in Valdrakken. I am sure you will aid us admirably. If you find yourself in need of the knife to match your fork, let me know and we will trade!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70881] = { id = 70881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fourth Challenge of Tyr: Resourcefulness", description = "The engine is close to reaching its full potential. All it requires now is a power core to process any essence put into it more efficiently.\n\nTyr left the knowledge of such devices with Watcher Irideus. Go into the Halls of Infusion and find him. I am sure he will help you with whatever you need.", progress = "You found Watcher Irideus?", completion = "Perhaps it was these enemies of order that Keeper Tyr wished to defend against. At least the loss of Watcher Irideus can still be a victory for us. By his power core we may power the engine and part of him shall always live on as creation of Tyr. \n\n<You can swear you see sadness cross over the maiden's face.>", objectives = "Obtain a Power Core from Watcher Irideus and defeat the Primal Tsunami in the Halls of Infusion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70882] = { id = 70882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70883] = { id = 70883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hand in Cultivation", description = "Greetings mortal, I have word from our Head Gardener Gryrmpech. The word is that the gardens are in a state of chaos, but I don't know if that is abnormal.\n\nThey assured me that they have it in hand--actually, 'in shovel' is the phrase they used. I am not sure what they are meaning; I am sure they will fill you in. Please, seek them out and they will outfit you appropriately for the situation.", completion = "A garden keeper needs their own weapons. Let me outfit you for battle. \n\nI have more tools of war if you need. I appreciate your help taming these wilds!", objectives = "Seek out Gryrmpech in the Gardens of Unity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70884] = { id = 70884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70885] = { id = 70885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70886] = { id = 70886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now THIS is Dragon Racing!", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70887] = { id = 70887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling Freedom", objectives = "My smaller kin are now able to freely explore the Dragon Isles. It pleases me to see them flourishing and enjoying new experiences.\n\nAllow me to show you more ways that they can express themselves to you and others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70888] = { id = 70888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubbing Shoulders With The Best", objectives = "Working day and night to outfit our forces is no small feat. It's arduous work, but I enjoy it. And I hear you have been a boon to our efforts. \n\nAs a show of thanks, I want you to take one of my armor pieces. Just one. If you require another, I will want something in trade.\n\nMake your choice quickly. I have work to do!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70889] = { id = 70889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting for Expertise", objectives = "You have returned, alchemist? I've been watching from afar, and I've seen you hard at work on your skills.\n\nTo reward your effort and mold you into an expert, I present you with these additional notes from our master alchemists. Study them carefully. Only with practice can you stand among the greatest of your craft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70890] = { id = 70890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Going on an Adventure!", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70891] = { id = 70891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fitting In", objectives = "If you are going to live or work in this city, you MUST blend in.\n\nI will make a custom garment for you in the latest style--I'll even give you your choice of color! Which flight do you feel most accentuates your eyes?\n\nIf you can't pick just one, then of course we can talk about multiple outfits. For a fair trade, of course!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70892] = { id = 70892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Your Start", objectives = "You wish to learn from our master alchemists? \n\nYou must improve your skills before requesting their guidance. But don't worry. I have some notes they're willing to give aspiring alchemists.\n\nThe notes will give you something to cut your fangs on! Practice crafting what's in them, and one day they'll entrust you with greater knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70893] = { id = 70893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Community Feast", description = "Our community feast is happening RIGHT NOW! This is when everyone pitches in and makes the best soup we can.\n\nYou should join us!", progress = "Как удачно, что ты застал пиршество. Мы проводим его всего-то по шесть-семь раз в день!", completion = "When everyone works together, the soup tastes GREAT!\n\nYou should try some when it's ready to eat!", objectives = "Perform 5 tasks in the Community Feast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70895] = { id = 70895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soaring in Style", objectives = "Ah, mortal. Word of your adventures is spreading throughout the city. All eyes are upon you as you and your drake ally soar above the skies!\n\nLet us speak further about the amazing variety of expression among dragonkind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70896] = { id = 70896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waist Not, Want Not", objectives = "My master Wrathion stationed me in this great forge. He's instructed me to lend a hand to adventurers such as yourself.\n\nI have some fine belts to offer in trade. Be sure to let the boss know I did my duty, eh?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70897] = { id = 70897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Coming of Age", objectives = "You have returned. The work has not lessened. In fact, my skills are in greater demand than ever before.\n\nSo, are you going to stand there all day or will you select one of my immaculate helms? Yes, I know how good they are. \n\nDo you wish to trade for something else? If you're not ready to trade, I must return to my work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70899] = { id = 70899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fifth Challenge of Tyr: Ingenuity", description = "As this was not how the Power Core was supposed to be obtained, it requires a re-attunement to the energies of the Engine. The resonance frequencies of the denizens of Tyrhold should bring the core to its full potential once more.\n\nThough I do not wish to sacrifice more of my brethren, I believe this is the only way this challenge may be completed.", progress = "How goes your challenge?", completion = "You have completed the last challenge. Though it comes at a loss, I believe it is for the greater good. Keeper Tyr meant for you to succeed.", objectives = "Attune Irideus' Power core with titanic energy from Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70900] = { id = 70900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Innovating the Engine", description = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. \n\nYou have proven yourself worthy and overcome all the challenges set before you. You may now unlock the Engine's full potential.", progress = "<The Engine hums quietly as you approach>", completion = "<With the new core installed, the Engine pulses with warm energy>", objectives = "Insert the newly attuned Power Core into the Engine of Innovation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70901] = { id = 70901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Collection of Creatures", objectives = "Greetings, mortal. I tend the grounds and the creatures that call them home--even stray proto-whelps.\n\nUnfortunately, there are more proto-whelps about than I can reasonably care for.\n\nHmm, you seem responsible. Would you like to take care of one? Later, if you would like a companion for your, uh, companion, please seek me out again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70902] = { id = 70902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting for Expertise", objectives = "Looks like you've been working hard, {name}. Wait, aren't engineers supposed to work smarter, not harder? Perhaps you're not cut out for engineering after all!\n\nMerely a jest, {race}. Here. The master engineers left you further notes to help you increase your skill. They've promised me their documentation is more thorough this time, but you be the judge of that. Good luck!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70903] = { id = 70903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wielding Titanic Might", objectives = "The study of Tyrhold and all titan artifacts in the Dragon Isles is critical to our efforts in fighting against the Primalists.\n\nThe weapons they left behind are especially important. I have recently discovered a great cache of them, and would like to award one to you in recognition of your efforts.\n\nAfter I catalog my findings, I would be willing to offer others in trade. But I ask that you bring me materials to further my research.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70904] = { id = 70904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Variety is the Spice of Life", objectives = "Dragons are ancient beings, as diverse in our appearances as you mortal races.\n\nI could teach you much about our lineage, and about the varied looks I have encountered.\n\nPerhaps this drake you fly with would be interested in hearing my tales and exploring the possibilities before them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70905] = { id = 70905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying with Our Colors", objectives = "We dragonkin proudly wear the colors of our flights! As you can see from my attire... and my scales. \n\nBut now scaled and scaleless alike can show that they stand with our renewed flights. Don a tabard and wear it with pride!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70907] = { id = 70907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruuk Hunts" }
quests[70908] = { id = 70908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruuk Hunts" }
quests[70909] = { id = 70909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting for Expertise", objectives = "I can tell by the smudges on your armor that you've been hard at work. And you've caught the attention of our masters as well! For your work, not for the cleanliness of your armor, to be clear...\n\nAs a reward, they have left more notes to help you learn. Study them and keep practicing, and perhaps one day you'll even surpass them. Good luck!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70910] = { id = 70910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteries in Paper and Glass", objectives = "Welcome back to my shop! I have many new goods that may be of interest.\n\nYour efforts in the Dragon Isles are the talk of the market, so I will let you have one item for free.\n\nIf anything else catches your eye, I'm certain we can strike a bargain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70911] = { id = 70911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armored and Ready", objectives = "Ah, the noble {class} returns from the path of adventure.\n\nA dragon's scales may be thick and tough, but it would be irresponsible to send our young into battle unprotected. Allow me to supply your drake with its first set of armor.\n\nSee me later if you would like to purchase another set. Other armors may be found throughout the Isles. Fair skies and strong winds!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70912] = { id = 70912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Accord's High Standards", objectives = "Carrying the banner of a dragonflight shows your support for what it stands for.\n\nPlease choose a banner and display it with pride. If you wish to trade for another, seek me out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70913] = { id = 70913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bear Our Mantle", objectives = "Back from your adventures, eh? Looks like you've seen a scrape or two. Bet you could use some new pauldrons. \n\nIf you don't see anything you like, there is a special set of armor I can make to order. It requires very specific materials, but that's not a problem for someone with your skills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70914] = { id = 70914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Breadth of Dragon Weaponry", objectives = "Ah, {class}. Welcome back to our forge. We have all heard tales of the amazing deeds you have done in service of Valdrakken.\n\nWe smiths serve the cause in our own way. To have a hero like you wielding one of my finest weapons would be an honor indeed!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70915] = { id = 70915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crowning Achievement", objectives = "My, my, you're certainly making a name for yourself. At least, that's what the boss tells us.\n\nAs for me, I spend my days making helms. Finest in the all the Isles! Take a look. My prices are fair.\n\nWell... fair enough, at least.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70916] = { id = 70916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beknownst and Glorious", objectives = "Hail, friend {name}. Your service to Valdrakken has been exceptional.\n\nLet it be known to all that you are truly an Ally of Dragons! \n\nAnd to reinforce our esteem of you and your deeds I am also giving you a Primal Infusion. Take it and make a great crafted piece from it that will continue to crush our enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70917] = { id = 70917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shoulder to Quack On", description = "<This duckling is full of nervous energy. It seems eager to escape its current predicament.>\n\n<Maybe the ecologists would know how to help it?>", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And {name} too, of course.", completion = "Thanks for bringing Dipper to us-- these ducklings are starting to pile up! Keep an eye out for any more.", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70918] = { id = 70918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quack for Your Life", description = "<This duckling is quacking frantically. If someone doesn't help it, the gorlocs will surely get annoyed!>\n\n<Maybe the ecologists would know how to help it?>", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And {name} too, of course.", completion = "Quackers is certainly a lively little guy, hmm? Thank you for bringing him to us-- there can't be too many more out there!", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70919] = { id = 70919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quacking Out for a Hero", description = "<This duckling has been bubbled so long that it's fallen fast asleep. It quacks softly as it snores.>\n\n<Maybe the ecologists would know how to help it?>", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And {name} too, of course.", completion = "Cheese and Quackers, hehe... I'd say that's about all the bubbled ducklings we can handle, {name}. Good work.", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70920] = { id = 70920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (Med Health)" }
quests[70921] = { id = 70921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (High Health)" }
quests[70922] = { id = 70922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (Mini Boss Steps)" }
quests[70924] = { id = 70924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Community Feast" }
quests[70925] = { id = 70925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Community Feast" }
quests[70926] = { id = 70926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Totems", progress = "Have you come to return our totems?", completion = "Ah! Our totems are very important to us. You have our thanks for returning them, young one!" }
quests[70927] = { id = 70927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Stolen Totems", progress = "Have you come to return our totems?", completion = "There are far too many in these isles that prey on our people. Losing our totems is like losing pieces of ourselves--our heritage, our legacy! You have our thanks for returning these to us, young one." }
quests[70928] = { id = 70928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Trophy", progress = "What have you brought me outsider?", completion = "Clan Shikaar knows a great hunting trophy when we see one. This will earn you much favor in our eyes." }
quests[70929] = { id = 70929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Hunting Trophies", progress = "What have you brought me, outsider?", completion = "Only the greatest of hunters can boast of this many great hunting trophies. You honor our hunt." }
quests[70930] = { id = 70930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Tea, No Shadeleaf", description = "Today is a celebration of tea - brewed, iced, and otherwise! Extravagant little cakes and biscuits too.\n\nBut there is a rare ingredient of the Isles I feel could add a whole new dimension of flavor! Deep within the crawler-infested domain of the Shiverweb Vale is a bush laden with the most wondrously uplifting leaf: Coldsnap Sagittate.\n\nThe Dragonscale Expedition was exploring that area recently. Perhaps one of them could assist?", completion = "A \"Coldsnap Sagittate\"? Hmm...", objectives = "Speak with Lilial Dawnburst in Shiverweb Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70931] = { id = 70931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispered Fragments", description = "I believe Valthrux is trying to communicate to us through the shard we recovered.\n\nWe can use this to our advantage as long as we keep our minds guarded from the artifact's influence.\n\nI was wrong about the Sundered Flame. They have unfortunately collected several shard fragments already. \n\nValthrux's whispers claim they're close to finding its location.\n\nGo and recover the shards from the Sundered Flame before they reach the artifact!", progress = "The whispers... they're... louder now. Do you have the fragments?", completion = "Excellent. With this many shards, I'll be able to easily locate the artifact.", objectives = "Recover 40 Whispering Fragments from the Sundered Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70932] = { id = 70932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Life of Spice", description = "To many, meat is essential for any true meal. But what is the essential for any true meat dish?\n\nSpice!!\n\nA spice that surpasses all others in terms of flavor, texture, and rarity lies within these Isles. Unfortunately, it can only be found on elementals that dwell in the depths of the Obsidian Stronghold. It's an area currently occupied by the Djaradin.\n\nPerhaps you can consult with a peculiar troll I met while passing through there. I believe his name was... Griftah.", completion = "What ya want?", objectives = "Speak with Griftah at the Obsidian Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70934] = { id = 70934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salamanther's Embrace" }
quests[70935] = { id = 70935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release: Islefin Dorado", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
quests[70936] = { id = 70936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Tuskarr Totems", objectives = "You there, young one! Our warriors take totems with them when they venture out into the Dragon Isles. Our totems are part of our livelihood--they are very important to us. Our enemies delight in taking them as trophies, and we can't let that happen! Please, return any totems you find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70937] = { id = 70937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Valthrux Once Was", description = "<To'tik whispers to you.> \n\nI don't like this. Mysterious artifacts whispering promises of greatness does not sound good.\n\nBut we can't just walk away... otherwise the Sundered Flame will get their hands on it. Whatever \"it\" is...\n\nI'm familiar with ruins like this. The blue dragons often left behind notes on their work. Keep your eyes open, and you may find some around.\n\nWe can use whatever evidence you find to warn Alia and Kattigat.", progress = "Did you find anything useful in the ruins?", completion = "Let's see what you've found...", objectives = "Find clues regarding what the artifact Valthrux really is.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70938] = { id = 70938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Community Feasts", description = "There you are, {name}! The soup's on! \n\nYou better hurry up and get to Iskaara. Big Kinook has been looking for you. \n\nOne time he told me to get a slimy, icky spinefish for the soup and I didn't want to, so I yelled: \"No, chef!\"\n\nHe was so mad I thought he was going to throw me in the soup!", completion = "Are you ready to make magic, adventurer? \n\nNo, I don't mean that hand wavy stuff some like to make. I mean the mystical aroma arts, the deep knowledge of ingredients and flavor, and the way a soup speaks to you to let you know what it needs. Is that you salivating? No? Must be me. \n\nLet's get cooking!", objectives = "Speak to Big Kinook at Iskaara in The Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70939] = { id = 70939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cooking Utensils", objectives = "Do you wanna be a great big soup master, too? \n\nI can't wait until I can see over the lip of the big pot! Then I'll finally be big enough to lead a feast!\n\nHere, this is for you! It'll help you on your soupy journey! Let me know if you wanna trade for anything else!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70940] = { id = 70940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskarr Champion's Tales", objectives = "The deeds of the tuskarr of the Dragon Isles are many!\n\nOver the years though, some of our stories have been lost. Many travelers never returned from their journeys with tales to tell. \n\nPlease, if you find any scrolls that document what our lost brethren were able to accomplish, bring them back to me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70941] = { id = 70941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing Holes", description = "Hello again! Did you know I'm gonna be the bestest fisherman in the village? I caught a giant piranha once. It tried to eat my face!\n\n<Rowie looks around distractedly.>\n\nOh yeah! I have a message for you. Nunvuq, back in Iskaara, wants to tell you about fishing holes.", progress = "Are the fish biting?", completion = "Hail, fellow fisher. \n\nI'm almost hesitant to tell you of these serene fishing holes. But I must, because not doing so would deny you a bounty of fish and also the pleasure of a relaxing time fishing.\n\nIn telling everyone I worry about crowding my fishing spot, but I'll admit I can only take so much of the quiet. A good conversation with fishing friends is an even better way to relax than fishing alone!", objectives = "Speak to Nunvuq at Iskaara in The Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70942] = { id = 70942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highland Fishing", objectives = "Greetings, friend! I see you're getting to know the ways of tuskarr, and thus the ways of the fish.\n\nIf you'd like, I could make you something that will allow you to tackle fishing in the highland pools of the Dragon Isles. Think you're up for the challenge?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70943] = { id = 70943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpooning", objectives = "Well now, you're a fast learner! Your fishing skills continue to improve.\n\nLet's see how you do with a spear. I'll craft for you your very first tuskarr harpoon. We shall see what you can land with it!\n\nI'm sure you won't fail to impress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70944] = { id = 70944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Fishing", objectives = "You've surpassed all of my expectations. And yet you continue to improve! You must hunger to learn more about fishing... \n\nHave you ever wondered what tasty morsels swim under the ice? Ice fishing takes skill, but I think you're up to the challenge.\n\nIf you bring me the right materials, I can get you started.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70945] = { id = 70945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netting More", objectives = "Your nets seem to be faring well in the fishing holes, but I think we can do better!\n\nIf you can get me the materials, I can help you craft some improvements to help you catch even more.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70946] = { id = 70946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One May Wield It", description = "What you found makes it sound like the artifact's power has doomed everyone who has used it so far.\n\nThe dragonspawn who lived here killed each other over it. The Sundered Flame seem like they're also getting corrupted by its influence too.\n\nThis isn't an artifact we need to recover. It's one that needs to be destroyed before it can harm anyone else.\n\nWe must convince Alia and Kattigat.", progress = "Let's hope this works...", completion = "This is worse than I thought. Way worse.", objectives = "Convince Alia to destroy Valthrux.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70947] = { id = 70947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure-Mad Trambladd" }
quests[70948] = { id = 70948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook, Line, and Swelter!", objectives = "Are you up for an exceptional challenge and added danger in your favorite pastime of fishing? \n\nI can craft something that will allow you to catch the most intense species of fish: the ones that call the lava rivers of the Dragon Isles home!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70950] = { id = 70950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skewering Even Bigger Fish", objectives = "How is that harpoon working for you? I'd love to hear the tale of your biggest catch with it!\n\nNow, what if I told you we could make harpooning even easier? I have some new designs that will do just that. Take a look!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70951] = { id = 70951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tackling the Tackle Box" }
quests[70952] = { id = 70952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned... or Hidden Caches", objectives = "Let me let you in on a little secret.\n\nSome of our less-than-friendly neighbors are jealous of our fishing prowess--and our fishing spots.\n\nThey trespass on our fishing claims and steal our tackle boxes, stashing them along the shores to not get caught in the act. Let me tell you what to look for, and you might just be able to help yourself to some useful supplies while you're out fishing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70953] = { id = 70953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskarr Headwear", objectives = "Greetings, dear friend. \n\nYou've been so kind to our community here in Iskaara. I have heard of your deeds and wanted to knit you something as a thanks.\n\nPlease, take your pick! I've made many hats to while away the hours of the long winters. I would be happy to trade you for others as well, if you wish!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70954] = { id = 70954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mounting Curiosity", objectives = "While gnolls remain the primary focus of my research, I'm very curious about the recently returned dragons as well. \n\nAfter intense study and observation, I began jotting down my notes on the subject. It's nowhere near complete, but when it is, I'm sure it will be a helpful guide to you.\n\nIn the meantime, would you like to look at one of my other manuscripts? I've started to trade them for items that will help continue my studies, so if you would like to learn more, visit me again!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70955] = { id = 70955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fascinating Fliers", objectives = "I saw a drake with a spotted pattern fly by yesterday! That was certainly a first for me, but you probably see many like it in your travels! \n\nThat said, I took detailed notes in case it's a new subspecies. It also had some other fascinating traits I had not seen previously!\n\nIf you'd like to read more of my observations, pick a manuscript to take with you. And if you'd like more reading material, I'll happily trade with you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70956] = { id = 70956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Azure Scales", objectives = "Do you enjoy poetry? Wait. If you don't, don't tell me. Hanu might hear you.\n\nIn our travels here, Hanu and I have noticed there are few blue-scaled beasts outside the Azure Span!\n\nI hypothesized some theories on the origin and nature of blue scales and jotted them down. And Hanu wrote a lovely poem about their perfect blue color! \n\nShe is shy about her writing, so she asked me to give it to you. Please, treasure it as I treasure her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70957] = { id = 70957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sea Out West", description = "Enjoying the greenery around our little scenery, {name}?\n\nIt reminds me of a dish I once tasted from a pair of dryad sisters and their kind treant friend. Sugarbough was their name! A resident of Shady Sanctuary on the western coast of the Plains.\n\nIt was a medley of fresh herbs, veggies, and spices. At the heart of this dish was the most delicious layer of sea kelp you have ever tasted!\n\nWhat? Never tasted sea kelp before? Well you simply must seek some out. And bring back enough to share, please!", completion = "Do you require assistance?", objectives = "Speak with Sugarbough at the Shady Sanctuary in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70958] = { id = 70958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finest Fungi at the Feast", description = "Fine dining is all about using the finest techniques on the finest ingredients, naturally. The food composed for fine dining is oft locked behind wealth and means, but we would never allow that at The Ruby Feast!\n\nMorsel has informed me of a perfect ingredient for today's theme. One so rare, so exquisite, that it... does not exist yet! Tantalizing, no?\n\nThe bronze have uncovered a portal to a dangerous future. One where a black truffle with untold flavor exists!\n\nYou must go!", completion = "Oh, {name}? My plate is full, but I will always make room at the table for you.", objectives = "Speak with Warden Captain Sinjoirmi at the Temporal Conflux in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70959] = { id = 70959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cute and Cuddly", objectives = "Do you love animals?\n\nOf course you do, who doesn't? Even the scary ones are pretty neat!\n\nYou wanna take care of one of the animals I tamed all by myself? I can tame more if you wanna trade for them, too--as long as you promise to take good care of them!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70960] = { id = 70960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trader's Apparel", objectives = "Hello, adventurer. \n\nI pride myself on my leatherworking skills. I would be honored if you would take this cloak as recognition for your efforts in helping us. \n\nIf you have a penchant for leather armor, I also am happy to make a set of our finest gear for trade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70961] = { id = 70961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shouldering the Needed Armor", objectives = "Hello again! You've done so much for us, friend! We'd be in dire straits indeed without your assistance. \n\nAs a token of our appreciation, I want you to have a set of my tufted shoulderpads. They should keep you warm on your adventures. \n\nIf you would like me to make you a sturdier set, simply bring me the materials to craft it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70962] = { id = 70962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Comfy Seat", objectives = "After a long day's work, it's good to relax. I've come up with a comfortable cushion to aid with that. It's very cozy! \n\nWould you like one? I'll gladly make one for you if you can bring me the materials to craft it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70963] = { id = 70963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrist Support", objectives = "Greetings, friend! To aid you in your journeys, I've crafted a fine set of wrist armor for you. \n\nDid I detect a scoff, youngster? Now, let me tell you about the importance of taking good care of your wrists! You should be doing stretches every few hours, and bracing them with armor when engaging in arduous activities! Don't hold them at a odd angle for prolonged periods of time and...\n\n<Arvik continues for some time.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70964] = { id = 70964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrug it On!", objectives = "<Arvik examines your wrist armor and grumbles in vague approval.>\n\nNow, have you been supporting your shoulders? Many don't realize it, but proper shoulderpads are important to help redistribute the weight of your other gear. You'll have back pain later in life without it! \n\n<Arvik rubs his back.> \n\nNot to mention protecting them from falling debris. With dragons, gnolls, centaurs... so much flying in or getting thrown around. Not safe out there. Please, consider my gear and keep your shoulders safe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70965] = { id = 70965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Watcher's Golden Girdle", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Watcher's Golden Girdle for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nYou may wish to start your search at our northern dig site, where Elementalist Taiyang has reported a malfunctioning Watcher causing trouble.", progress = "Do you have something for the archives?", completion = "Whew, glad I don't have to wear this heavy thing!\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Watcher's Golden Girdle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70966] = { id = 70966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Made Easier", objectives = "Have you traveled much? You don't look like you have--you're missing one of my sturdy backpacks!\n\nA good pack will make all the difference out in the world. You've helped my people out many times, so I want to offer you one of my best basic packs. \n\nI have many other packs as well! If you would like to offer a fair trade, I will gladly trade you for more.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70967] = { id = 70967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishy Entertainment", objectives = "Fishing is great. I love it! I eat, sleep, and dream it. And when I'm not fishing, I craft fishing gear!\n\nIf I've learned anything from my many years fishing, it's that you also have to have a little fun out there--change things up, think outside the net!\n\nHere's some gear I dreamed up to help you new fishers along! You can have one for free, but if you'd like both, I'll gladly trade you for the other.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70968] = { id = 70968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of the Cloth, of the Community", objectives = "It is my honor to bestow upon you this gift, for all you have done for the tuskarr. The colors of our community are woven into its cloth, symbolizing how we all are woven together into a community--one that you are now a part of.\n\nWear it with pride, my friend!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70969] = { id = 70969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming One of Our Community", objectives = "Greetings, friend! The tales of your deeds have spread across the Azure Span from Iskaara to Imbu to the Gleamlet. You've proven yourself time and time again, and we are grateful for it.\n\nChieftain Brena has declared that you have earned an honored place within our community... and within our family. You will forever be known as one of Iskaara. Thank you for everything you've done, friend. Please also take this Primal Infusion you can use to have a great item crafted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70970] = { id = 70970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Intentions", description = "I may know where the artifact is. Alia was whispering frantically when you brought all the shards back.\n\nShe kept saying something about a \"cave\" and how the spiders seemed attracted to it.\n\nThere's no cave in the area in front of us... which leads me to believe there might be one deeper in the ruins.\n\nWe'll stay here and keep your escape path open, {name}. Please save Alia and destroy this cursed artifact.", progress = "Let's hope this works...", completion = "To'tik was right. This place is cursed. \n\nWe'll let the Kirin Tor know what happened here, {name}. Thank you for your help. \n\nThis is a lesson I won't soon forget...", objectives = "Stop Alia Sunsoar and destroy the artifact Valthrux.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70971] = { id = 70971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms for Every Arm", objectives = "Have you come to spar? No? Shame.\n\nI know what you have done for our people. It would be an honor if you would wield one of my weapons. Pick which ever one pleases you. \n\nTake your time. I realize my collection is massive. \n\nIf you would like more of my weapons, continue to prove your mettle. Bring me items showing you are not losing your martial prowess, and I will trade you for more armaments!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70972] = { id = 70972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Loyal, Lanky Steeds", objectives = "Our ottuks choose only to be ridden by our most esteemed warriors.\n\nI think it is time to see if one will bond with you. They are fiercely loyal, but they love to have fun!\n\nI will leave you and the ottuks to decide which will be your bonded companion. \n\nOttuks that are large enough to ride are rare, and their tack is expensive. If you wish to train another one, my fellow trainers and I must ask for a large trade in return.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70975] = { id = 70975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Everblazing Fireheart", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Everblazing Fireheart for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing a massive fire elemental under control of the Primalists in the north that may provide an opportunity to acquire one.", progress = "Do you have something for the archives?", completion = "The Primalists sure do love their elementals, huh?\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Everblazing Fireheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70976] = { id = 70976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slacking and Sledding", description = "As you may know, the children of Iskaara are fiercely independent. They learn from a young age to fend for themselves.\n\nIt's a rite of passage for many of the older kids to sneak off to the iceberg southeast of here. Kiopo, the eldest of our children, is out there right now. Tell him I sent you, and he should offer you one of our sleds!\n\nAh, that reminds me of my younger days... out there with my friends...", completion = "Oh, Murik sent you? He's really nice, so you must be really nice too!\n\nWhy did he send you? A sled? Of course I can give you a sled! \n\nWe have two types. But if you want both, I'm gonna need some good stuff for a trade!", objectives = "Seek out Kiopo on the island to the southeast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70977] = { id = 70977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scaps Packs", objectives = "YOU BRING SCAPS HUNGRIES? BRING FEESH?\n\nNO?\n\n<SCAPS watches as you gesture towards his backpack.>\n\nWANT PACK-BACK? \n\n<SCAPS considers this.> \n\nYOU TAKE PACK-BACK, OKAY?\n\nBUT NEXT TIME--BRING FEESH! THEN GIVE PACK! \n\nME HUNGRIES!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70978] = { id = 70978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Champion's Tales", objectives = "Young one! The Dragon Isles are full of stories that date back generations upon generations.\n\nIf you venture deep within the great halls and vaults of this land, I am sure you can find and reclaim scrolls that detail these stories. If you bring them to me, I'll have a special gift for you in return!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70979] = { id = 70979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmaton" }
quests[70981] = { id = 70981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savory Seas", description = "The smell of the sea! Do you smell it, {name}? Do you smell the multitude of minerals, laden with thick sea salt? Do you??\n\nSuspiciously absent from the delights here today is a rare variety of fish I once tasted near the Iskaara's home in Azure Span. Two Tuskarr fellows were simply roasting one over a fire, and it filled that glacial tundra with the most savory aroma!\n\nSee if you can not find one for us. I know our patrons will be just as ensorcelled by the sea's flavor as I was that day.", completion = "Please tell me you aren't here with that Ironjaw fellow. We had enough gorloc troubles before he showed up...", objectives = "Speak with Wayun in Whaler's Nook of the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70983] = { id = 70983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'nank Shorescour" }
quests[70984] = { id = 70984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surge Breaker" }
quests[70985] = { id = 70985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lonely Scout", description = "I know, I know, it's silly. A centaur and a dryad, right? We can't be more different.\n\nBut ever since I first laid eyes on the Emerald Gardens, I really have wanted to get to know one better. I just can't seem to say or do anything to keep them interested in me.\n\nI've heard they're into... plants. And cute baby animals. And maybe killing poachers, but I don't even know where to start.\n\nPlease, you can talk to them, right? Could you ask around and find out what they like? Then maybe I can have a shot.", progress = "Any luck? Please tell me there's hope.\n\nIt would just be so nice.", completion = "Flowers!!\n\n<Scout Santuun smacks her palm on her forehead.>\n\nIt's so obvious. I was overthinking it, like I always do.\n\nThank you, {name}, you're the best!", objectives = "Speak to dryads in Shady Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70986] = { id = 70986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Private Shikzar" }
quests[70987] = { id = 70987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of Starch", description = "What could be better than a meal you can carry while you explore?\n\nStreet foods are the essence of busy cities this great world over. But not every meal is set for mobility. The core of great on-the-go cuisines is a starch that will hold strong while moving. Breads, potatoes, rices, and beyond are the heart of hand-sized dining.\n\nI would like to treat my Pandaren peer here to a flavorful specimen known as Leapmaize. Morsel introduced it to me when we first met near the titan ruins in the Waking Shores.", completion = "Great, you're finally here. I need a dozen more cushions, three tapestries, a scrollshelf, a few more of those enchanted brooms, and...\n\nWait. You're not with the Expedition. What do you want?", objectives = "Speak with Meliane Enorath at the Life Vault Ruins in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70988] = { id = 70988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Egg's the Thing", description = "\"All the world's an egg.\" That is how the saying goes, right?\n\nEggs! They are the core of confections, and one of the great catalysts of culinary creation! They are the fat that puts acids, heats, and salts on their highest pedestals, to their highest potentials!\n\nOur Isles are teeming with fowl of immense strength, but the Breezehunters of the Plains lay eggs primed with flavor!\n\nThey often nest on the Eastern side of the Plains, so ask around the outpost in Rusza'thar Reach.", completion = "Oh! Hello!\n\nSorry about the mess here! I mean, I didn't cause it or anything, I'm just apologizing that you have to deal with it.\n\nNot to imply you wouldn't be able to handle it! Just saying that you might be uncomfortable with the state our furniture is currently in.\n\nNot that this is how we want the furniture set up! We don't want it set up like this, we were planning to... uhm...\n\nWhat did you say you needed?", objectives = "Speak with Ilana at Rusza'thar Reach in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70989] = { id = 70989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Part of a Pack", description = "Perhaps your bakar needs to be shown the proper way to hunt by his own kind.\n\nYou may borrow some of our trained bakar. Take them and bring down the drake that circles the area. \n\nLet us see how Taivan behaves in a pack!", progress = "Have you brought down that drake yet? My bakar should be more than enough for your quarry.", completion = "<Jadar shakes his head.>\n\nVery disappointing. I'm afraid Taivan just does not have it in him to hunt like a Shikaar. Even with other bakar fighting beside him, he could not shake his unwillingness to attack his enemy. \n\nWhat a waste!", objectives = "Hunt the Ravenous Proto-Drake with Taivan and the pack of hunting bakar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70990] = { id = 70990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If There's Wool There's a Way", description = "While most of our wool comes from our own argali flocks, we do sometimes need to pull from the land when the flock grows thin.\n\nThe nearby plains are home to wild argali - they tend to be more temperamental than our clan's flock. If you could take this blade and attempt to shear their wool, it would be a great service to Aylaag.", progress = "Take care to avoid the horns. They're as sharp as any knife.", completion = "I will get this wool to the artisans who can use it. Thank you.", objectives = "Shear cliffhoof argali for their wool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70992] = { id = 70992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Lost Tuskarr Kite", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Lost Tuskarr Kite for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing such a kite attached to a tuskarr transport along the western coast, but none have been able to reach it as the transport keeps it aloft and out of reach when traveling.", progress = "Do you have something for the archives?", completion = "I wonder what all the little scrolls on here say? The archivists'll have fun with this one.\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Lost Tuskarr Kite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70994] = { id = 70994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drainage Solutions", description = "Want the honor of assisting world-renowned Head Geologist of the Dragonscale Expedition? That's right. I'm exactly who you think I am. And I'm in a bind!\n\nI was perusing this river for new sedimentary samples, but then the water started to walk away with the most interesting pieces of silt!\n\nI have here my patented water entrapment device, but it's in desperate need of someone to march around and siphon those elementals into it.\n\nThink you're up to the task?", completion = "Yes, that's it! That's the composition I was looking for! Thank you! Finally, someone knows when to listen to me.\n\nDo me a favor and don't mention this to anyone back at basecamp, got it? My thesis is still in progress, and I'm supposed to be writing about volcanic sedimentary sources. I'm sure you can understand, yeah?", objectives = "Siphon 8 Glittery Streams in the cave east of the Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70995] = { id = 70995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Fenistrasza's Skull", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out Fenistrasza's Skull for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing it in the possession of an outcast djaradin in the western mountains, but no one has been able to convince him to part with it yet.", progress = "Do you have something for the archives?", completion = "<Cataloger Jakes frantically tries to prevent the magma pouring out of the skull's eye sockets from burning her other documents.>\n\nOkay, now I KNOW the archivists are putting out these requests just to annoy me!\n\nNevertheless, I'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find Fenistrasza's Skull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70996] = { id = 70996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Kelp for My Friends", description = "Well gosh, it sure sounds like Grimtusk is in a pickle. I'd say I'm done with conflicts on the mainland, but...\n\nFrostbite and I have got a history. And a score to settle.\n\nOh, fiddle! I can't leave the others here undefended... We've an issue with an elemental causing trouble at the beach. I'm the only one who can keep him at bay. Slippery fella... literally.\n\nTell you what. If you will deal with the elemental for me, I'll mosey on over to Grimtusk's camp.\n\nWhaddaya say, champ?", progress = "How's it going? Did you get that slippery, slimy elemental yet?", completion = "Well I'll be! Guess I'm heading out to help my pal Grimtusk after all!", objectives = "Defeat the Wild Kelp Elemental on Longclaw Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70997] = { id = 70997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Ruby Lifeband", description = "<The posted sign is written in hasty scratches.>\n\nExpedition members have reported a Primalist attack on the Ruby Life Pools, threatening the destruction of countless artifacts stored by our dragon allies there.\n\nToddy and Naleidea urge all combat-ready members to join the fight, and seek out the Ruby Lifeband if you are able.\n\nIt is a unique, priceless artifact that must be preserved.\n\nIf acquired, please deliver to Cataloger Jakes for safekeeping until the dragons may safely retrieve it.", progress = "Do you have something for the archives?", completion = "They say this was handcrafted by Alexstrasza herself? Thank the tides you saved it.\n\nI'll ensure this is properly documented and researched while we have it for safekeeping.", objectives = "Find the Ruby Lifeband in the Ruby Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71000] = { id = 71000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barst Recruited", description = "Well a deal's a deal. If Grimtusk needs a hand killing Frostbite once and for all, then I'm in.\n\nWhat hate I have left in me I reserve for Frostbite. Did Grimtusk tell you what happened? \n\nAll of us who hunted with Grimtusk thought we were unstoppable. Until we met Frostbite. \n\nFrostbite didn't just defeat us. He humiliated us in front of everyone in the hideaway. \n\nWe were all defeated and left bloodied and battered at the hideaway. Frostbite used us as an example.\n\nNow it's time for payback.", completion = "Here's Barst. Just as... annoying as ever.", objectives = "Let Grimtusk know you've recruited Barst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71001] = { id = 71001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Earthbound Primordial Core", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Earthbound Primordial Core for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nRecent learnings from records recovered from the Obsidian Citadel indicate it may have once been stored in the Dragon's Hoard of Neltharus, although it's current location is unclear.", progress = "Do you have something for the archives?", completion = "I can tell this one's going to be a troublemaker... I'll get the magically sealed containers Naleidea enchanted for problem cases.\n\nDon't worry, I'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Earthbound Primordial Core in Neltharus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71002] = { id = 71002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Spell Ever", description = "<Gently levitating and emanating with arcane magic, this enchanted book contains countless spells and enchantments created by the chaotic yet beautiful mind of Millhouse Manastorm.>", completion = "<Using your own knowledge of the arcane, you begin browsing through Millhouse's notes until you find a worn out page filled with numerous drawings of ducks, big and small. \n\nIn the very center of it are words to Millhouse's newest conjuration with a curious hand note below: \n\n\"Best Spell Ever.\">", objectives = "Read \"Manastorming for Beginners\" and discover Millhouse's secret spell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71004] = { id = 71004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Ohuna Mass-Binding Totem", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Ohuna Mass-Binding Totem for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported a particularly powerful Primalist in the Windsong Rise of the Ohn'ahran Plains, who appears to wield the rumored powers of this totem.", progress = "Do you have something for the archives?", completion = "Not sure I see what all the fuss is about with this one. Feels like every other dirty hunk of rock I've held before.\n\nOh well, I'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Ohuna Mass-Binding Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71005] = { id = 71005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Fangfall", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the legendary blade Fangfall for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nThe sword was reportedly fractured long ago, but expedition members have reported that the Sundered Flame is recovering fragments of it in ruins of the Ohn'aran Plains.", progress = "Do you have something for the archives?", completion = "Ooo, I love puzzles! I should ask the archivists if I can help with putting these back together!\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find 100 Fragments of Fangfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71007] = { id = 71007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Disoriented Wishtail", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the legendary Wishtail for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing a colorful fish matching its purported appearance inside a massive water elemental in Azure Span.", progress = "Do you have something for the archives?", completion = "<Cataloger Jakes puts her ear close to the fish and listens intently while whispering to it.>\n\nI know you can talk, little guy. Just say something and grant me a wish! It'll be easy!\n\n<Cataloger Jakes sighs.>\n\nIt was worth a shot. I'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Disoriented Wishtail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71008] = { id = 71008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Stoneheart's Stone Heart", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out Stoneheart's Stone Heart for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing Stoneheart in a cave of central Azure Span.", progress = "Do you have something for the archives?", completion = "This used to be a beating furbolg heart? The Primalists really are something else...\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find Stoneheart's Stone Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71009] = { id = 71009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementary, My Dear Drakonid", description = "Grimtusk wants to take another crack at Frostbite, eh? I hate to turn him down, but I left that life behind for the life of a scholar.\n\nI'm trying to uncover the history--and make history. But I'm stumped by this esoteric riddle here in these ancient ruins. \n\nThe riddle is this: if you touch a nearby crystal, it says \"follow the pattern.\" But I haven't the faintest idea what that means!\n\nTell you what. If you can help me crack this riddle, I'll go help Grimtusk finish Frostbite off once and for all.", progress = "\"Follow the pattern.\" What could that mean?", completion = "Oh dear... I'm not going to lie, {name}, this isn't my proudest moment.", objectives = "Help Varsek solve the mystery of the Ancient Outlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71010] = { id = 71010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Temporal Spyglass", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Temporal Spyglass for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported overhearing a dwarf bragging about his magical spyglass in the inns of Southern Thaldraszus. We recommend focusing your search in that region.", progress = "Do you have something for the archives?", completion = "<Cataloger Jake shakes her head as she keeps the spyglass far from her eyes.>\n\nNo thanks. The present holds enough headaches for me. Don't need the past or present butting their unwanted faces in too.\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Temporal Spyglass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71011] = { id = 71011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Torrential Lily", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Torrential Lily for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing a powerful Primalist in Gelikyr Overlook of Thaldraszus with a magical flower pinned to her collar. It is unknown if that is the legendary Torrential Lily, but it is a good place to start your search.", progress = "Do you have something for the archives?", completion = "Just what we needed, another flower that leaks some weird liquid...\n\n<Cataloger Jakes rolls her eyes.>\n\nI'll ensure this is properly documented, researched, and archived for the expedition.", objectives = "Find the Torrential Lily.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71012] = { id = 71012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varsek Recruited", description = "Seems like I'll be able to solve the mysteries of this place just fine in the future. \n\nLet's just never speak of this to Old Grimtusk, OK?\n\nI'll make my way to his hideaway. I think I'll enjoy taking out some pent up aggression on Frostbite.", completion = "There's Varsek. Guess he finally solved whatever puzzle he was after, eh?", objectives = "Let Grimtusk know you've recruited Varsek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71013] = { id = 71013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Vengeance on an Empty Stomach", description = "Now that we've gotten back to what we aimed to do, we need to have a talk tusk to tusk. That gnoll Frostbite? The one you spoke to?\n\nWe've got a history with him.\n\nThis may take awhile to explain. You go and get some fish while I talk, pup. We need to feed everyone. They need their strength for what's next.", progress = "It's hard work fishing out here. That's the point.", completion = "Now you know what's at stake. \n\nTime to get moving.", objectives = "Fish 3 Frozen Tail Darters within Grimtusk's Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71014] = { id = 71014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Far Furbolg Friend", description = "Barst was one of the toughest furbolgs I've ever known. It says something about Frostbite that his pack beat him in a fight.\n\nLast I heard, Barst left for some island off the coast of Iskaara. Called it his \"retirement\" or some other garbage.\n\nTell Barst it's time to get back into action. \n\nOh, and don't be fooled by the way he talks. He'll tear you in two if you look at him wrong.", completion = "Well, look at you! You made it all the way over here! How can I help you?", objectives = "Find Barst on Longclaw Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71015] = { id = 71015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Brawn, No Brains", description = "Varsek is one of the toughest drakonids you'll ever meet. One of the dumbest ones too, but he'll never admit that.\n\nHe got spooked after Frostbite and started re-evaluating his life or... something. Said he never got to study the ruins left behind by his ancestors. Ran off to be a \"scholar\".\n\nGet Varsek back here. He doesn't belong there anyhow!", completion = "It's very nice to meet you, but as you can see, I'm a bit busy trying to solve this puzzle.", objectives = "Find Varsek in the Ancient Outlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71016] = { id = 71016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtusk's Sister", description = "Last is my sister, Naluki. She helps run the inn at Iskaara now.\n\nJust give her this letter. \n\nDon't open it.", completion = "Why, well aren't you just a fresh fish hopping out of the water! \n\nWhat's this? A letter from Grimtusk?", objectives = "Deliver Grimtusk's letter to his sister, Naluki, in Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71017] = { id = 71017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naluki's Letter", description = "Let me guess, Grim told you not to open the letter, right?\n\nLooks like you did as you were told. No wonder he trusts you so much! \n\nGive him this fish head for me. He'll know what it means.", completion = "<It's hard to tell, but you think you see a slight smile on Grimtusk's face. It quickly fades away.>\n\nThis will do.", objectives = "Deliver Naluki's fishhead to Old Grimtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71018] = { id = 71018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", progress = "The power contained in these shards will allow us to quickly access The Clutchwarren.", completion = "These should allow us to ascend to Diurna's chamber more readily.", objectives = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71019] = { id = 71019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", progress = "The power contained in these shards will allow us to quickly access The Clutchwarren.", completion = "These should allow us to ascend to Diurna's chamber more readily.", objectives = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Heroic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71020] = { id = 71020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", progress = "The power contained in these shards will allow us to quickly access The Clutchwarren.", completion = "These should allow us to ascend to Diurna's chamber more readily.", objectives = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71022] = { id = 71022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reign of the Ram", description = "Since the argali don't seem to have much respect for Taivan, we should see if he can handle the herd's ram next.\n\nHe's the boss of all the argali here, and quite the stubborn thing. If Taivan can assert dominance over the ram, the herd will start obeying him.\n\nYou can find him just over there, on the hill. Good luck, Taivan. If this doesn't work, I'm afraid there's not much hope for him being a herder!", progress = "The herd's ram is on the hill just over there. Hopefully Taivan handles this task a little better.", completion = "That could have gone better. Sorry, friend, but I don't think Taivan is cut out for this. \n\nHe's a very nice bakar, but doesn't quite seem smart enough to figure out how to get the argali into the pen, or aggressive enough to take command of the herd away from the ram. \n\nI'm afraid I'm going to have to send you back to Selbekh with bad news.", objectives = "Command Taivan to confront the herd's Stubborn Ram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71023] = { id = 71023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Valdrakken Accord", description = "Your deeds are certainly in line with your fabled reputation prior to coming to the Dragon Isles. \n\nI wish to assist you further by providing you with additional supplies. Seek me out in Valdrakken.", completion = "It is my part to acknowledge those whose efforts further the accord and by acknowledgement aid them further. I take pride in aiding one such as yourself. Please take these so they may continue to aid your efforts against the Primalists.", objectives = "Speak with Unatos in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71024] = { id = 71024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos and Commotion", description = "{name}! Did you hear the noise? There has been an incident on the bottom floor.\n\nOne of my trusted investigators, Erima, was there first. He will require assistance gathering evidence while he tries to interview the crowd.", progress = "May I see that map?", completion = "I am grateful Captain Drine sent you to help.\n\nYou have keen eyes and are resourceful.", objectives = "Help Erima investigate the incident at the bottom floor of the Seat of the Aspects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71025] = { id = 71025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges.\n\nIf you gather some friends, I know a place you can show the other side who is truly superior.\n\nAnd to make it interesting, if you are successful I have a prize for you.", objectives = "Slay 25 Level 70 Alliance anywhere within the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71026] = { id = 71026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges.\n\nIf you gather some friends, I know a place you can show the other side who is truly superior.\n\nAnd to make it interesting, if you are successful I have a prize for you.", completion = "Well done, {class}. Well done indeed.", objectives = "Slay 25 Level 70 Horde anywhere within the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71027] = { id = 71027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Mara'nar the Thunderous", description = "Looking for a mighty hunter to take down a rampaging beast!\n\nA thunder lizard named Mara'nar the Thunderous worked his way from Thunderspine Thicket to Primordial Vale, disrupting local wildlife. It has electrified water, knocked down trees, and broken duck nests.\n\nThis menace must be stopped. Slay him and bring one of his plates to Khansguard Jebotai as proof.\n\nMay Ohn'ahra guide you.", progress = "Hail, traveler.", completion = "Mara'nar has been slain. May his kin learn to stay within their own lands.", objectives = "Slay Mara'nar the Thunderous in Primordial Vale and retrieve one of his plates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71028] = { id = 71028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Tactics: Blessing of Ohn'ahra", description = "Your renown with the Maruuk grows. Listen closely, and I will teach you to call upon a blessing of Ohn'ahra to protect you and your allies.", completion = "May the winds of Ohn'ahra guide and protect you.\n\nReturn when your renown grows, and I will train you further.", objectives = "Select a blessing of Ohn'ahra for use in the Grand Hunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71029] = { id = 71029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Tactics: Companion Training", description = "Your renown with the Maruuk grows once more. For your efforts, I will teach you to command your hunting companion more effectively in combat.", completion = "Your growth strengthens the clan.\n\nReturn again when your renown grows, and I will continue your training.", objectives = "Choose an additional companion ability for use in the Grand Hunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71030] = { id = 71030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Tactics: Shikaar Mentorship", objectives = "Your renown with the Maruuk rises. Seek out other Shikaar during the grand hunt, and they will improve your combat prowess while the hunt is on.\n\nCome to me again when your renown grows, and I will train you more.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71031] = { id = 71031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Tactics: Proof of Prowess", objectives = "I see your renown with the Maruuk has grown once more. Let me show you how to carry the thrill of victory through multiple foes.\n\nReturn again when your renown grows, and I will train you further.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71032] = { id = 71032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Tactics: Apex Hunter", objectives = "Your renown has reached its peak, champion. I have one more technique to teach you. No quarry, no matter how powerful, will stand before you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[71034] = { id = 71034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Artifacts", progress = "Do you have something for the archives?", completion = "Ooo, a new artifact. Let me log it in the ledger and note you returned it. \n\n<Cataloger Jakes makes a notation in her ledger.> \n\nGot it! Keep them coming!" }
quests[71035] = { id = 71035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiple Dragon Isles Artifacts", progress = "Do you have something for the archives?", completion = "Look at all these artifacts! This might take a minute. \n\n<Cataloger Jakes hastily makes several notes in her ledger.> \n\nGot it! Off with you, now! Come back if you have more!" }
quests[71036] = { id = 71036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Artifacts", progress = "Do you have something for the archives?", completion = "Ooo, a new artifact. Let me log it in the ledger and note you returned it. \n\n<Cataloger Jakes makes a notation in her ledger.> \n\nGot it! Keep them coming!" }
quests[71037] = { id = 71037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiple Dragon Isles Artifacts", progress = "Do you have something for the archives?", completion = "Look at all these artifacts! This might take a minute. \n\n<Cataloger Jakes hastily makes several notes in her ledger.> \n\nGot it! Off with you, now! Come back if you have more!" }
quests[71038] = { id = 71038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Trophy", progress = "What have you brought me, outsider?", completion = "Clan Shikaar knows a great hunting trophy when we see one. This will earn you much favor in our eyes." }
quests[71039] = { id = 71039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Hunting Trophies", progress = "What have you brought me, outsider?", completion = "Only the greatest of hunters can boast of this many great hunting trophies. You honor our hunt." }
